import sys

def find_lexicographic_string(s, t):
    n = len(s)
    for i in range(n):
        if s[i] < t[i]:
            if chr(ord(s[i]) + 1) < t[i]:
                return s[:i] + chr(ord(s[i]) + 1) + 'a' * (n - i - 1)
            elif i + 1 < n and s[i] + 1 != t[i]:
                return s[:i] + chr(ord(s[i])  + 1) + 'a' * (n - i - 2) + 'b'
    return 'No such string'

input = sys.stdin.read().split()
s = input[0]
t = input[1]
print(find_lexicographic_string(s, t))
